def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def load_rows():
    rows = []
    with DATA.open(newline="") as f:
        for r in csv.reader(f):
            dt = datetime.strptime(r[0] + " " + r[1], "%Y.%m.%d %H:%M")
            rows.append((dt, float(r[2]), float(r[3]), float(r[4]), float(r[5]), int(r[6])))
    return rows


def font(size=16):
    candidates = [
        "/System/Library/Fonts/Supplemental/Arial.ttf",
        "/System/Library/Fonts/Supplemental/Helvetica.ttf",
    ]
    for p in candidates:
        if Path(p).exists():
            return ImageFont.truetype(p, size)
    return ImageFont.load_default()


def draw_chart(chart_id, decision_text, rows):
    decision = datetime.strptime(decision_text, "%Y-%m-%d %H:%M")
    eligible = [r for r in rows if r[0] <= decision]
    week_open_i = None
    for i in range(len(eligible) - 1, -1, -1):
        if eligible[i][0].weekday() == 6 and eligible[i][0].hour == 17 and eligible[i][0].minute == 0:
            week_open_i = i
            break
    if week_open_i is None:
        raise RuntimeError(f"No week open for {chart_id}")
    cut = eligible[week_open_i:]
    if not cut or cut[-1][0] != decision:
        raise RuntimeError(f"Decision row missing for {chart_id}: {decision}")

    csv_path = SLICES / f"{chart_id}_visible_only.csv"
    with csv_path.open("w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["timestamp_utc_minus_5", "open", "high", "low", "close", "volume"])
        for r in cut:
            w.writerow([r[0].strftime("%Y-%m-%d %H:%M"), f"{r[1]:.5f}", f"{r[2]:.5f}", f"{r[3]:.5f}", f"{r[4]:.5f}", r[5]])

    W, H = 1500, 820
    left, right, top, bottom = 100, 40, 90, 100
    pw, ph = W-left-right, H-top-bottom
    lows = [r[3] for r in cut]; highs = [r[2] for r in cut]
    lo, hi = min(lows), max(highs); pad = max((hi-lo)*0.06, 0.0005)
    lo -= pad; hi += pad
    def x(i): return left + (i + .5) * pw / len(cut)
    def y(v): return top + (hi-v) * ph / (hi-lo)

    im = Image.new("RGB", (W,H), "#0d1620"); d = ImageDraw.Draw(im)
    for j in range(6):
        yy = top + j*ph/5
        d.line((left,yy,W-right,yy), fill="#24384a", width=1)
        val = hi-j*(hi-lo)/5
        d.text((8,yy-8), f"{val:.5f}", font=font(14), fill="#aebdca")
    first8 = cut[:min(32,len(cut))]
    rhi, rlo = max(r[2] for r in first8), min(r[3] for r in first8)
    d.rectangle((left,y(rhi),W-right,y(rlo)), outline="#3ca6d8", width=2)
    d.text((left+8,y(rhi)+5), "First 8 hours (context only)", font=font(14), fill="#63c9f4")
    candle_w = max(2, int(pw/len(cut)*0.62))
    for i,r in enumerate(cut):
        _,o,h,l,c,_ = r; xx=x(i); col="#2ac48a" if c>=o else "#ef596f"
        d.line((xx,y(h),xx,y(l)), fill=col, width=1)
        y1,y2=y(o),y(c)
        d.rectangle((xx-candle_w/2,min(y1,y2),xx+candle_w/2,max(y1,y2)+1), fill=col)
    d.text((left,20), f"{chart_id} — GBP/USD M15 — HistData Arm A (fixed UTC−5)", font=font(24), fill="white")
    d.text((left,52), f"VISIBLE THROUGH {decision_text} ONLY — NO LATER CANDLES INCLUDED", font=font(18), fill="#ffcf55")
    d.text((left,H-65), f"Week open visible: {cut[0][0]:%Y-%m-%d %H:%M}  |  Decision: {decision:%Y-%m-%d %H:%M}", font=font(16), fill="#b9c7d3")
    d.text((left,H-38), "The blue band is an administration aid, not a claim that the course fully defines every box/session boundary.", font=font(15), fill="#8ca1b3")
    img_path = CHARTS / f"{chart_id}_visible_only.png"
    im.save(img_path)
    return img_path, csv_path, cut[0][0], decision, len(cut)


