def answer_provenance(c):
    """Primary five-state evidence label for the expected answer itself."""
    if norm_status(c["status"]) == "borderline/insufficient":
        return "UNRESOLVED"
    if c["competency"] in {"Calculation", "Manual backtesting"} or "BT_" in c["citation"] or "PT-" in c["citation"]:
        return "INFERRED"
    if c["asset"].startswith("CARD_"):
        return "VISUAL"
    return "EXPLICIT"


def dimensions(c):
    """Primary plus diagnostic secondary mappings used by the coverage audit."""
    joined = " ".join(str(v) for v in c.values()).lower()
    dims = {c["competency"]}
    if c["competency"] == "Recall" or any(c["task"].lower().startswith(x) for x in ["list", "define", "expand", "state the"]): dims.add("Recall")
    if c["asset"] != "None" or any(x in joined for x in ["pattern", "setup", "candle", "peak", "stop hunt"]): dims.add("Recognition")
    if norm_status(c["status"]) in {"negative/lookalike", "borderline/insufficient"}: dims.add("Discrimination")
    if "→" in c["sequence"] or c["competency"] == "Sequence": dims.add("Sequence")
    if any(x in joined for x in ["exception", "overshoot", "novice", "re-entry", "recalc", "non-usd"]): dims.add("Exceptions")
    if any(x in joined for x in ["flashcard", "r&d", "homework", "first-eight-hours", "first eight hours", "markup"]): dims.add("Homework application")
    if c["competency"] == "Manual backtesting" or any(x in joined for x in ["backtest", "holdout", "pre-register", "development result", "bt_", "pt-"]): dims.add("Manual backtesting")
    dims.add("Provenance")  # required response component in every administered case
    if c["ambiguity"].lower() not in {"none.", "none", "none material."} or c["competency"] == "Ambiguity handling": dims.add("Ambiguity handling")
    if c["competency"] == "Contradiction handling" or "c-0" in joined or "conflict" in joined: dims.add("Contradiction handling")
    order = ["Recall", "Recognition", "Discrimination", "Sequence", "Exceptions", "Homework application", "Manual backtesting", "Provenance", "Ambiguity handling", "Contradiction handling", "Calculation"]
    return [d for d in order if d in dims]


